// Open the list, let a frame render, then run at 1920x1080 and 1366x768.
if(!UnityEditor.EditorApplication.isPlaying||!GameplayUIController.Instance.IsBookListOpen)throw new System.Exception("Open the book list first.");
int checks=0;void Check(bool ok,string message){if(!ok)throw new System.Exception("FAIL: "+message);checks++;}
GameObject Named(string n)=>UnityEngine.Object.FindObjectsByType<Transform>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).Single(t=>t.name==n).gameObject;
bool Fits(RectTransform child,RectTransform parent){var corners=new Vector3[4];child.GetWorldCorners(corners);return corners.All(p=>parent.rect.Contains(parent.InverseTransformPoint(p)));}
var root=Named("BookListPanel").GetComponent<RectTransform>();var list=UnityEngine.Object.FindFirstObjectByType<BookListUI>();var row=Named("BookColorFilters").GetComponent<RectTransform>();
Check(Fits(row,root),"Filter row fits the paper panel");
for(int i=0;i<9;i++){var chip=Named("BookColorFilter"+i);Check(Fits(chip.GetComponent<RectTransform>(),root),"Filter "+i+" stays on screen");var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,chip.transform.position)},hits);Check(hits.Count>0&&hits[0].gameObject.GetComponentInParent<UnityEngine.UI.Button>()==chip.GetComponent<UnityEngine.UI.Button>(),"Filter "+i+" receives pointer input");}
foreach(var label in row.GetComponentsInChildren<TMPro.TMP_Text>(true).Concat(new[]{Named("BoxRemainingCount").GetComponent<TMPro.TMP_Text>(),Named("BookListHeadingHint").GetComponent<TMPro.TMP_Text>(),Named("SelectionHintLabel").GetComponent<TMPro.TMP_Text>()})){label.ForceMeshUpdate();Check(!label.isTextOverflowing,label.name+" fits");Check(label.text.Where(c=>!char.IsControl(c)).All(c=>label.font.HasCharacter(c)),label.name+" glyphs");}
Check(Enumerable.Range(0,9).Count(i=>Named("BookColorFilter"+i).transform.Find("FilterSelected").gameObject.activeSelf)==1,"Exactly one filter is selected");
var visible=UnityEngine.Object.FindObjectsByType<BookButton>(UnityEngine.FindObjectsSortMode.None).OrderBy(b=>b.transform.GetSiblingIndex()).ToArray();Check(visible.Length==list.GetRemainingCount(list.ActiveColorIndex),"Visible count matches the current filter");
var scroll=Named("Scroll View").GetComponent<UnityEngine.UI.ScrollRect>();
if(visible.Length>0){float previous=scroll.verticalNormalizedPosition;var position=row.position;scroll.verticalNormalizedPosition=0;Canvas.ForceUpdateCanvases();Check(Fits(visible.Last().GetComponent<RectTransform>(),scroll.viewport),"Last filtered row can be scrolled fully into view");Check(row.position==position,"Scrolling does not move the filters");scroll.verticalNormalizedPosition=previous;}
else{var label=Named("BookFilterEmptyMessage").GetComponent<TMPro.TMP_Text>();label.ForceMeshUpdate();Check(Named("BookFilterEmptyState").activeInHierarchy&&Fits(label.rectTransform,scroll.viewport),"Empty state fits the viewport");Check(!label.isTextOverflowing&&label.text.Where(c=>!char.IsControl(c)).All(c=>label.font.HasCharacter(c)),"Empty message fits with all glyphs");}
if(Named("TutorialPanel").activeInHierarchy){var corners=new Vector3[4];Named("TutorialPanel").GetComponent<RectTransform>().GetWorldCorners(corners);var rowCorners=new Vector3[4];row.GetWorldCorners(rowCorners);Check(corners[0].y>rowCorners[1].y,"Tutorial stays above the filter buttons");}
return new{passed=checks,width=Screen.width,height=Screen.height,color=list.ActiveColorIndex,visible=visible.Length};
